(7342585, 1147547, 38032, '<td valign="top">What a beautiful image. Somewhat horrific to human eyes I suppose but look at that foliage popping in. Lovely decay and ominous tone.</td>', 'What a beautiful image. Somewhat horrific to human eyes I suppose but look at that foliage popping in. Lovely decay and ominous tone.', '2015-04-15 08:52:30.000000', NULL, 1),
(7342586, 1147249, 38032, '<td valign="top">Beautiful and artsy yet humble and interesting. The fly almost looks like an intellectual posing for a portrait. The diagonal comp will score points as well.</td>', 'Beautiful and artsy yet humble and interesting. The fly almost looks like an intellectual posing for a portrait. The diagonal comp will score points as well.', '2015-04-15 08:53:58.000000', NULL, 1),
(7342588, 1147545, 38032, '<td valign="top">Great bokeh obviously. I also liked the toned-down saturation.</td>', 'Great bokeh obviously. I also liked the toned-down saturation.', '2015-04-15 08:54:48.000000', NULL, 1),
(7342590, 1147440, 38032, '<td valign="top">Different and appealing.</td>', 'Different and appealing.', '2015-04-15 08:55:37.000000', NULL, 1),
(7342591, 1147372, 38032, '<td valign="top">Certainly a modern approach which I find very appealing. Detached from the chaotic natural elements and interrupted with well-found, clean angles. The color pallet is just right. 9</td>', 'Certainly a modern approach which I find very appealing. Detached from the chaotic natural elements and interrupted with well-found, clean angles. The color pallet is just right. 9', '2015-04-15 08:58:56.000000', NULL, 1),
(7342592, 1147563, 38032, '<td valign="top">love the muted pastel look here.</td>', 'love the muted pastel look here.', '2015-04-15 09:02:21.000000', NULL, 1),
(7342593, 1147517, 38032, '<td valign="top">Makes me want to know more. Nice comp and harsh shadows fit the subject.</td>', 'Makes me want to know more. Nice comp and harsh shadows fit the subject.', '2015-04-15 09:03:05.000000', NULL, 1),
(7342594, 1147199, 38032, '<td valign="top">Pretty macro-ish shot. Great bokeh and colors.</td>', 'Pretty macro-ish shot. Great bokeh and colors.', '2015-04-15 09:03:45.000000', NULL, 1),
(7342595, 1147169, 38032, '<td valign="top">Interesting literal look-inside the gardening process.</td>', 'Interesting literal look-inside the gardening process.', '2015-04-15 09:05:13.000000', NULL, 1),
