(7344259, 1147440, 109227, '<td valign="top">Love the dew on the rails.  Nicely composed.</td>', 'Love the dew on the rails.  Nicely composed.', '2015-04-21 22:49:12.000000', NULL, 1),
(7344260, 1147528, 109227, '<td valign="top">Nicely composed.</td>', 'Nicely composed.', '2015-04-21 22:49:35.000000', NULL, 1),
(7344261, 1147537, 109227, '<td valign="top">This looks like a lot of work and I am happy I don''t have to clean it up, lol.  The lengths we go to for DPC.  Very imaginative.</td>', 'This looks like a lot of work and I am happy I don''t have to clean it up, lol.  The lengths we go to for DPC.  Very imaginative.', '2015-04-21 22:50:28.000000', NULL, 1),
(7344262, 1147439, 109227, '<td valign="top">I have never seen a lawn mower like this; very small.  Good thing she is headed down hill, coming back up may be daunting.  Nice light.</td>', 'I have never seen a lawn mower like this; very small.  Good thing she is headed down hill, coming back up may be daunting.  Nice light.', '2015-04-21 22:51:59.000000', NULL, 1),
(7344263, 1147237, 109227, '<td valign="top">Great composition and portrait.  It does not say "lawn" to me, but still a good image.</td>', 'Great composition and portrait.  It does not say "lawn" to me, but still a good image.', '2015-04-21 22:52:53.000000', NULL, 1),
(7344264, 1146964, 109227, '<td valign="top">I like the poetic title that fits with the poetic image although I am not sure what I am looking at.</td>', 'I like the poetic title that fits with the poetic image although I am not sure what I am looking at.', '2015-04-21 22:53:55.000000', NULL, 1),
(7344265, 1147199, 109227, '<td valign="top">My kind of macro; I love poking around in the grass in the morning dew.  Nice.</td>', 'My kind of macro; I love poking around in the grass in the morning dew.  Nice.', '2015-04-21 22:55:08.000000', NULL, 1),
